/** Definitions written for the classroom. Aliases are matched as whole words. */
export type LearningTerm = { id: string; label: string; meaning: string; example: string; aliases: string[]; courses?: string[] };
const term = (id: string, label: string, meaning: string, example: string, aliases: string[] = [label], courses?: string[]): LearningTerm => ({ id, label, meaning, example, aliases, courses });

export const learningGlossary: LearningTerm[] = [
  term("heritage-template", "Héritage de templates", "Un gabarit de base contient la structure commune d’une page et des zones nommées. Un gabarit enfant reprend cette base puis remplit certaines zones, par exemple le contenu central. Cela partage le menu et le pied de page sans les recopier. Ce mécanisme de présentation se distingue de l’héritage entre classes du langage.", "Dans Django, {% extends 'base.html' %} choisit la base et {% block content %}...{% endblock %} remplit une zone. Blade propose ses propres directives pour le même besoin de présentation.", ["heritage", "extends", "layout", "layouts"], ["django-web", "php-web"]),
  term("fichier-web", "Fichier, dossier et extension", "Un fichier est un document enregistré avec un nom. Un dossier regroupe des fichiers. L’extension, après le dernier point, indique leur type : .html pour le document, .css pour ses styles. Un chemin indique où trouver le fichier, relativement au dossier courant ou depuis un emplacement complet.", "Dans mon-site/images/portrait.webp, images est un dossier et .webp l’extension du fichier portrait.", ["fichier", "fichiers", "dossier", "dossiers", "extension", "chemin"], ["html-css-web"]),
  term("lien-hypertexte", "Lien hypertexte et destination", "Un lien permet de rejoindre une ressource ou une partie du document. L’élément a contient le texte cliquable et href annonce la destination. Une URL peut viser un autre site ; une ancre comme #competences vise un élément du document portant cet identifiant.", "<a href=\"#competences\">Mes compétences</a> conduit vers l’élément id=\"competences\".", ["hypertexte", "liens", "href"], ["html-css-web"]),
  term("css-typographie", "Couleur et typographie CSS", "La typographie concerne la présentation du texte. font-family choisit les familles de caractères, font-size la taille et line-height la hauteur d’une ligne. color règle la couleur du texte ; background peut régler son fond. Une couleur hexadécimale commence ici par # et se distingue d’un sélecteur d’identifiant.", "p { color: #173d55; font-size: 1rem; line-height: 1.6; } rend les paragraphes lisibles avec un espace adapté entre leurs lignes.", ["typographie", "font-family", "font-size", "line-height", "hexadecimal"], ["html-css-web"]),
  term("viewport", "Viewport", "La zone dans laquelle le navigateur affiche le document. Sa largeur disponible peut différer de celle d’un grand écran d’ordinateur. La métadonnée viewport aide notamment les navigateurs mobiles à utiliser une largeur adaptée à l’appareil.", "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"> est placée dans head pour préparer l’affichage mobile.", ["viewport"], ["html-css-web"]),
  term("sql-filtre", "Filtre WHERE et motif LIKE", "WHERE conserve les lignes dont la condition est satisfaite. AND combine des exigences, OR propose des possibilités et des parenthèses rendent l’ordre clair. LIKE cherche un motif : % remplace une suite de caractères et _ un caractère dans les cas courants. Ce filtre ne trie pas le résultat.", "WHERE nom LIKE 'Ra%' sélectionne les noms qui commencent par Ra selon les règles de comparaison du moteur.", ["WHERE", "LIKE", "AND", "OR", "filtre", "motif"], ["lang-sql"]),
  term("sql-pagination", "Tri et pagination SQL", "Le tri choisit l’ordre des lignes avec ORDER BY. La pagination découpe le résultat en portions : LIMIT borne la taille et OFFSET saute des lignes dans les exemples SQLite. Sans ORDER BY, l’ordre n’est pas garanti. Un identifiant en complément du tri aide à départager les valeurs égales.", "ORDER BY nom, id LIMIT 10 OFFSET 20 demande dix lignes après les vingt premières, dans l’ordre annoncé.", ["ORDER BY", "LIMIT", "OFFSET", "pagination"], ["lang-sql"]),
  term("qt-cpp", "Qt et ses widgets C++", "Qt est une bibliothèque qui permet notamment de construire des interfaces graphiques en C++. Un widget est un élément d’interface : fenêtre, texte ou bouton. Les signaux annoncent des événements ; les slots ou fonctions connectées y réagissent. Qt Designer décrit une interface dans un fichier .ui.", "QLabel affiche un texte ; QPushButton fournit un bouton dont le signal clicked peut être relié à une action.", ["Qt", "QLabel", "QPushButton", "QApplication", "QMainWindow", "Designer"], ["lang-cpp"]),
  term("flexbox-native", "Flexbox dans React Native", "Le système de disposition répartit les composants sur un axe. flexDirection choisit la direction, justifyContent organise l’axe principal et alignItems l’axe transversal. Les propriétés s’écrivent en camelCase dans un objet JavaScript. Les conventions et valeurs par défaut diffèrent du CSS web, notamment avec une direction column par défaut.", "Une View avec { flexDirection: 'row', alignItems: 'center' } aligne ses enfants horizontalement et les centre sur l’axe transversal.", ["Flexbox", "flexDirection", "justifyContent", "alignItems"], ["react-native-mobile"]),
  term("propriete-css", "Propriété CSS", "Le nom d’un aspect de présentation à régler. Une déclaration associe cette propriété à une valeur, avec deux-points entre les deux. Le sélecteur indique quels éléments reçoivent la règle. Une propriété CSS n’est pas une propriété d’objet JavaScript.", "Dans h1 { color: blue; }, color est la propriété et blue sa valeur. font-size règle la taille du texte.", ["propriete", "proprietes"], ["html-css-web"]),
  term("poo", "POO / OOP", "Programmation orientée objet ; en anglais Object-Oriented Programming. Une manière d’organiser un programme autour d’objets réunissant des données et des opérations. Une classe décrit un plan, une instance un objet concret et une méthode une opération associée.", "Un objet Compteur conserve sa valeur et fournit une méthode incrementer pour la faire évoluer.", ["POO", "OOP", "orientee objet", "oriente objet", "orientee objets"]),
  term("self-this", "self et this", "Des façons de désigner l’instance courante dans différents langages. En Python, self est le nom conventionnel du premier paramètre d’une méthode d’instance, pas un mot réservé. En Java et C++, this a une signification définie par le langage. En PHP, on utilise $this.", "Dans une méthode Python, self.score désigne le score de l’objet qui reçoit l’appel.", ["self", "this", "$this"], ["lang-python", "django-web", "lang-java", "java-mobile", "java-web", "lang-cpp", "lang-php", "php-web"]),
  term("pointeur", "Pointeur et adresse mémoire", "En C et C++, un pointeur peut conserver l’adresse d’un objet en mémoire. Dans une déclaration, * annonce un type pointeur ; dans une expression, * peut accéder à l’objet pointé et & peut prendre une adresse. Le sens d’un symbole dépend de sa position. Une adresse doit rester valide avant son utilisation.", "Pour int valeur = 3; int *p = &valeur;, p contient une adresse et *p permet d’accéder à valeur.", ["pointeur", "pointeurs", "adresse memoire", "dereferencement"], ["lang-c", "lang-cpp"]),
  term("entete-c", "En-tête, prétraitement et édition des liens", "Un en-tête .h ou .hpp contient notamment des déclarations partagées. #include demande au préprocesseur d’en intégrer le contenu. La compilation prépare des unités objets ; l’édition des liens les assemble avec les bibliothèques nécessaires pour produire le programme.", "Inclure une déclaration de fonction ne remplace pas la présence de sa définition lors de l’édition des liens.", ["#include", "en-tete", "en-tetes", "edition des liens", "pretraitement"], ["lang-c", "lang-cpp"]),
  term("std", "std, cout et cin", "std est l’espace de noms de la bibliothèque standard C++. Un espace de noms regroupe des identifiants et évite certaines collisions. std::cout représente un flux de sortie ; std::cin un flux d’entrée. Les opérateurs << et >> insèrent ou extraient des valeurs dans ces usages.", "std::cout << \"Bonjour\" écrit le texte dans la sortie de la console.", ["std", "cout", "cin", "namespace", "espace de noms"], ["lang-cpp"]),
  term("queryset", "QuerySet Django", "Une collection décrivant des résultats de requête. On peut généralement la filtrer et la trier avant son évaluation. La requête est exécutée quand ses résultats sont nécessaires, par exemple lors de son parcours. Une collection de résultats n’est pas un seul objet modèle.", "Task.objects.filter(done=False).order_by('created_at') décrit les tâches à terminer triées par date.", ["QuerySet", "QuerySets", "objects", "order_by"], ["django-web"]),
  term("modelform", "ModelForm et cleaned_data", "ModelForm est un formulaire Django construit à partir d’un modèle et de champs choisis. is_valid() lance les validations ; cleaned_data expose ensuite les valeurs nettoyées acceptées. save() peut créer ou modifier l’instance associée selon la configuration.", "Un formulaire de tâche peut accepter title sans laisser le visiteur choisir un propriétaire arbitraire.", ["ModelForm", "cleaned_data", "is_valid"], ["django-web"]),
  term("gtk", "GTK", "GIMP Toolkit : bibliothèque de composants d’interface graphique, utilisée ici avec C. Elle fournit des fenêtres et widgets. Les signaux annoncent des événements et des fonctions de rappel y réagissent. Une boucle d’événements garde l’application disponible pour les interactions.", "Un bouton peut émettre clicked ; le callback associé change le modèle et met l’affichage à jour.", ["GTK", "GTK 4", "GtkApplication", "signal", "signaux"], ["lang-c"]),
  term("javafx", "JavaFX, FXML et Scene Builder", "JavaFX est une bibliothèque Java d’interface graphique. Stage représente notamment une fenêtre et Scene son contenu. FXML est un format XML qui décrit l’arbre d’interface. Scene Builder permet de travailler visuellement sur ce fichier ; le contrôleur Java assure les actions.", "Un fx:id permet au contrôleur de retrouver un contrôle déclaré dans le FXML avec les réglages d’injection appropriés.", ["JavaFX", "Stage", "Scene", "FXML", "Scene Builder", "@FXML"], ["lang-java"]),
  term("map-filter-reduce", "map, filter, forEach et reduce", "Des opérations de collection : map transforme chaque valeur, filter sélectionne selon une condition, forEach exécute une action pour chaque valeur et reduce combine les valeurs dans un accumulateur. Les détails de retour et de mutation se vérifient pour le langage utilisé.", "En JavaScript, [1, 2].map(n => n * 2) produit [2, 4] ; filter(n => n > 1) produit [2].", ["map", "filter", "forEach", "reduce"], ["javascript-web", "lang-javascript", "lang-typescript", "react-web", "vue-web"]),
  term("fetch", "fetch et réponse réseau", "Dans les environnements qui la proposent, fetch lance une requête et fournit une promesse de réponse. Lire le JSON demande une étape supplémentaire. Une réponse HTTP 404 ou 500 ne rejette pas automatiquement la promesse : il faut vérifier response.ok ou le statut selon le cas.", "const response = await fetch(url); puis vérifier response.ok et appeler await response.json() sépare transport, statut et données.", ["fetch", "response.ok", "response.json"], ["javascript-web", "lang-javascript", "lang-typescript", "react-web", "vue-web", "node-web", "react-native-mobile"]),
  term("jpa", "JPA et Hibernate", "JPA signifie Jakarta Persistence, une spécification pour relier des objets Java à des données persistantes. Hibernate est une implémentation courante. Une entité annotée décrit généralement une table ; un repository facilite les opérations d’accès dans Spring Data.", "Une recherche par identifiant renvoie une entité ou une absence à traiter, pas automatiquement une réponse HTTP.", ["JPA", "Hibernate", "repository", "repositories", "@Entity"], ["java-web"]),
  term("html", "HTML5", "HyperText Markup Language : langage de balisage hypertexte. HTML donne un rôle au contenu d’un document. Le chiffre 5 désigne une évolution de ce langage ; le standard continue d’évoluer.", "<h1>Bienvenue</h1> désigne un titre principal, indépendamment de sa couleur.", ["HTML", "HTML5"]),
  term("css", "CSS3", "Cascading Style Sheets : feuilles de style en cascade. CSS choisit la présentation des éléments HTML. La cascade départage les règles qui ciblent une même propriété ; ce n’est pas seulement « la dernière règle gagne ».", "h1 { color: blue; } colore les titres h1 en bleu.", ["CSS", "CSS3"]),
  term("balise", "Balise et élément HTML", "Une balise marque le début ou la fin d’un élément. Dans <p>Bonjour</p>, <p> ouvre, </p> ferme, Bonjour est le contenu. L’ensemble constitue un élément paragraphe. Les chevrons < et > font partie de la syntaxe.", "Une balise donne du sens au contenu ; CSS peut ensuite en changer l’apparence.", ["balise", "balises", "element html", "elements html"]),
  term("orpheline", "Balise orpheline / élément vide", "Nom courant d’un élément HTML sans contenu ni balise fermante. img, br, hr, input, meta et link sont des éléments vides. En HTML, la barre finale de <img /> ne ferme pas un élément comme elle le ferait en XML.", "<img src=\"photo.webp\" alt=\"Mon portrait\"> n’a pas de </img>. Évite d’utiliser br pour créer des marges : utilise CSS.", ["orpheline", "orphelines", "element vide", "elements vides", "img", "meta", "br", "input", "link"]),
  term("head", "head : les informations sur la page", "Le mot anglais head signifie « tête ». L’élément <head> rassemble les métadonnées : informations qui décrivent le document, comme son titre, son encodage et ses liens CSS. Son contenu n’est généralement pas dessiné dans la zone principale de la page. head et header sont différents.", "<head><title>Mon portfolio</title></head> donne un nom à l’onglet, pas un titre visible dans le contenu.", ["head", "metadonnee", "metadonnees"]),
  term("body", "body : le contenu de la page", "Body signifie « corps ». L’élément <body> contient le contenu principal destiné à la consultation : titres, paragraphes, images, formulaires. Il se place après head dans html.", "<body><h1>Mon portfolio</h1><p>Bonjour !</p></body> décrit ce que la page présente.", ["body"]),
  term("h1", "h1, p et title", "h signifie heading, « titre de section ». h1 est le niveau principal ; h2 à h6 organisent les sous-parties. p désigne un paragraphe. title nomme le document dans l’onglet et dans d’autres interfaces du navigateur. La hiérarchie des titres exprime le sens, pas une taille à choisir au hasard.", "<title>Accueil</title> va dans head ; <h1>Bienvenue</h1> et <p>Mon texte</p> vont dans body.", ["h1", "h2", "h3", "h6", "<title", "paragraphe", "titres HTML"]),
  term("attribut", "Attribut HTML", "Une information ajoutée dans la balise ouvrante pour préciser l’élément. Elle s’écrit souvent nom=\"valeur\". class regroupe des éléments pour le style, id identifie un élément, href indique une destination et src une source.", "Dans <a href=\"/profil\">Mon profil</a>, a est l’élément, href est l’attribut et /profil sa valeur.", ["attribut", "attributs", "href", "src", "className"]),
  term("utf8", "UTF-8", "Unicode Transformation Format, encodage sur des unités de 8 bits. Un encodage décrit comment les caractères sont représentés en octets. UTF-8 permet notamment d’écrire des accents et de nombreuses écritures dans les fichiers.", "<meta charset=\"UTF-8\"> annonce l’encodage du document HTML.", ["UTF-8", "UTF8", "encodage", "charset"]),
  term("doctype", "DOCTYPE", "Une déclaration placée au début du document HTML. <!DOCTYPE html> demande au navigateur le mode standard, pour éviter d’anciens comportements de compatibilité. Ce n’est pas une balise de contenu et elle ne se ferme pas.", "Écris <!DOCTYPE html> avant <html lang=\"fr\">.", ["DOCTYPE"]),
  term("dom", "DOM", "Document Object Model : modèle objet du document. Le navigateur représente la page comme un arbre de nœuds, avec des parents et des enfants. Cette représentation en mémoire peut être inspectée et modifiée. Le fichier HTML est le texte source ; le DOM est le document construit à partir de ce texte.", "Dans body → h1 → texte, h1 est un enfant de body. JavaScript peut retrouver ce h1 et modifier son texte sans réécrire le fichier source.", ["DOM"]),
  term("selecteur", "Sélecteur CSS", "Une expression qui choisit les éléments concernés par une règle de style. Le sélecteur précède les accolades ; entre celles-ci, chaque déclaration associe une propriété à une valeur.", "p cible les paragraphes, .carte les éléments class=\"carte\", #profil l’élément id=\"profil\". color: blue est une déclaration.", ["selecteur", "selecteurs", "cascade", "specificite"]),
  term("boite", "Modèle de boîte", "Le navigateur traite les éléments comme des boîtes : contenu au centre, padding autour du contenu, border autour du padding, margin à l’extérieur. box-sizing: border-box inclut padding et bordure dans une largeur déclarée.", "Avec width: 200px et padding: 20px, border-box garde une largeur totale de 200px, hors margin.", ["box model", "modele de boite", "padding", "margin", "border-box"]),
  term("responsive", "Responsive / adaptatif", "Une interface responsive ajuste sa disposition aux dimensions disponibles. Elle doit rester lisible et utilisable sur mobile, tablette et ordinateur. Des tailles fluides et des media queries permettent de changer la présentation sans changer le contenu.", "@media (max-width: 40rem) peut faire passer une grille de trois colonnes à une colonne.", ["responsive", "adaptatif", "media queries", "media query", "viewport"]),
  term("flexbox", "Flexbox", "Modèle de disposition CSS sur un axe principal à la fois. Un conteneur display: flex organise ses enfants ; justify-content agit sur l’axe principal et align-items sur l’axe transversal. flex-direction choisit le sens de l’axe.", "display: flex; gap: 1rem; aligne des cartes avec un espace entre elles.", ["Flexbox", "justify-content", "align-items"]),
  term("grid", "CSS Grid", "Modèle CSS de disposition en lignes et colonnes. Le conteneur définit une grille et ses enfants s’y placent. fr représente une fraction de l’espace disponible dans une piste de la grille.", "grid-template-columns: repeat(2, 1fr) crée deux colonnes de même part.", ["CSS Grid", "grid-template-columns", "grid-template-rows"]),
  term("semantique", "Sémantique HTML", "Choisir un élément selon le sens du contenu. nav annonce une zone de navigation, main le contenu principal, article un contenu autonome. header est une zone d’introduction visible et se distingue de head, qui décrit le document.", "Un button déclenche une action ; un lien a conduit vers une destination.", ["semantique", "header", "nav", "article", "footer"]),
  term("formulaire", "Formulaire", "Ensemble de champs qui recueillent des données et une action de soumission. Un label nomme un champ ; input, select et textarea reçoivent les valeurs. La validation vérifie leur forme avant utilisation.", "Un champ type=\"email\" required aide le navigateur à vérifier une adresse, mais le serveur doit aussi valider les données reçues.", ["formulaire", "formulaires", "label", "textarea", "required"]),
  term("aria", "ARIA et A11y", "ARIA signifie Accessible Rich Internet Applications : attributs qui renseignent les technologies d’assistance sur certains composants. A11y abrège accessibility : 11 lettres entre a et y. L’accessibilité commence par de bons éléments HTML, des libellés et un usage au clavier.", "aria-expanded=\"true\" annonce qu’un panneau contrôlé par un bouton est ouvert.", ["ARIA", "A11y", "accessibilite"]),
  term("seo", "SEO", "Search Engine Optimization : optimisation pour les moteurs de recherche. Une structure claire, des titres pertinents et un contenu accessible aident les outils à comprendre la page ; cela ne garantit pas une position dans les résultats.", "Le titre du document et un h1 descriptif aident à identifier son sujet.", ["SEO", "referencement"]),
  term("javascript", "JavaScript / JS", "Langage de programmation utilisé dans les navigateurs et dans d’autres environnements comme Node.js. Un moteur exécute les instructions, généralement par interprétation et compilation JIT. Il est distinct du langage Java.", "console.log(2 + 3) calcule puis affiche 5 dans la console.", ["JavaScript", "JS"]),
  term("variable", "Variable, déclaration et affectation", "Une variable est un nom utilisé pour retrouver une valeur. Déclarer introduit ce nom dans le programme ; affecter associe une valeur au nom. La réaffectation remplace la valeur associée. Le signe = d’affectation n’est pas le test d’égalité.", "En JavaScript, let score = 0 déclare score et lui affecte 0 ; score = 1 le réaffecte.", ["variable", "variables", "affectation", "reaffectation", "declaration", "let", "const", "val", "var"]),
  term("type", "Type de donnée", "Une catégorie de valeurs qui détermine les opérations possibles. Un entier représente un nombre sans partie décimale, une chaîne représente un texte et un booléen représente vrai ou faux. Les noms exacts et les conversions dépendent du langage.", "Le texte \"12\" et le nombre 12 sont différents : la conversion doit être choisie explicitement quand on veut calculer.", ["type", "types", "booleen", "boolean", "string", "integer", "double"]),
  term("fonction", "Fonction, paramètre et argument", "Une fonction regroupe des instructions sous un nom pour les réutiliser. Un paramètre est un nom annoncé lors de sa définition ; un argument est une valeur fournie lors de l’appel. return renvoie un résultat au code appelant ; afficher un résultat et le renvoyer sont deux actions distinctes.", "Dans addition(a, b), a et b sont les paramètres ; addition(2, 3) fournit les arguments 2 et 3.", ["fonction", "fonctions", "parametre", "parametres", "argument", "arguments", "return"]),
  term("condition", "Condition et comparaison", "Une condition choisit une branche d’instructions selon un résultat vrai ou faux. Une comparaison produit ce résultat. Dans plusieurs langages, = affecte une valeur alors que == ou === compare ; il faut apprendre les règles du langage utilisé.", "if (score > 0) signifie : exécuter ce bloc seulement si score est supérieur à zéro.", ["condition", "conditions", "comparaison", "comparaisons", "if", "elif", "elseif", "when"]),
  term("boucle", "Boucle et itération", "Une boucle répète des instructions. Chaque passage est une itération. Une boucle for parcourt souvent une collection ; while répète tant qu’une condition reste vraie. Une boucle doit pouvoir s’arrêter quand le traitement est terminé.", "Parcourir les trois noms d’une liste produit trois itérations.", ["boucle", "boucles", "iteration", "iterations", "for", "while", "foreach"]),
  term("tableau", "Tableau / liste", "Une collection de valeurs repérées par une position appelée indice. Les premiers indices sont souvent 0, 1, 2. Les capacités et le redimensionnement dépendent du langage : un tableau C et une liste Python n’ont pas le même fonctionnement.", "Dans [\"Tiana\", \"Amina\"], l’indice 0 désigne Tiana.", ["tableau", "tableaux", "Array", "ArrayList", "vector", "liste Python"]),
  term("objet", "Objet et propriété", "Un regroupement de données nommées et, selon le langage, de comportements. Une propriété est une information accessible par un nom. Un objet littéral JavaScript peut être créé sans déclarer de classe.", "Dans { nom: \"Tiana\", age: 23 }, nom et age sont des propriétés.", ["objet", "objets", "propriete", "proprietes"]),
  term("classe", "Classe", "Une description commune de données et de comportements pour des objets. On peut la comparer à un plan : elle précise les attributs et les méthodes que ses instances possèdent ou peuvent utiliser. Les détails varient selon le langage.", "Une classe Compteur peut définir une valeur et une méthode incrementer.", ["classe", "classes", "class"]),
  term("instance", "Instance", "Un objet concret créé à partir d’une classe. Deux instances partagent les méthodes définies par leur classe mais peuvent conserver des états différents. Une instance n’est ni le fichier source ni la classe elle-même.", "Deux compteurs peuvent avoir les valeurs 2 et 7 tout en provenant de la classe Compteur.", ["instance", "instances", "instanciation"]),
  term("constructeur", "Constructeur", "Une opération appelée lors de la création d’un objet pour préparer son état initial. Son nom et sa syntaxe changent selon le langage. En Python, __init__ initialise l’instance après sa création ; en PHP, __construct est le constructeur.", "Un constructeur peut recevoir une valeur de départ et l’enregistrer dans l’objet.", ["constructeur", "constructeurs", "__init__", "__construct"]),
  term("methode", "Méthode et encapsulation", "Une méthode est une fonction associée à une classe ou à un objet. L’encapsulation regroupe données et comportements et limite les modifications directes pour maintenir des règles. private et public contrôlent cet accès dans plusieurs langages.", "Une méthode ajouterMontant peut vérifier un montant avant de modifier le solde.", ["methode", "methodes", "encapsulation", "getter", "setter", "getters", "setters", "private", "public", "protected"]),
  term("heritage", "Héritage de classes", "Une classe peut reprendre et spécialiser les capacités d’une autre. extends exprime souvent cette relation. Une méthode redéfinie remplace un comportement pour la sous-classe. L’héritage de templates HTML est un autre mécanisme, expliqué dans son propre contexte.", "Une classe CompteEpargne peut spécialiser un Compte tout en ajoutant sa propre règle de calcul.", ["heritage", "extends", "override", "polymorphisme"]),
  term("portee", "Portée", "La zone du programme où un nom est accessible. Une variable locale d’une fonction n’est normalement pas accessible depuis l’extérieur de cette fonction. En JavaScript, let et const ont une portée de bloc.", "Un score déclaré dans les accolades d’un if ne devient pas automatiquement une variable globale.", ["portee", "scope", "closure", "closures", "fermeture", "fermetures"]),
  term("null", "null, None, nil et valeur absente", "Ces mots représentent l’absence de valeur dans différents langages. Le nom exact et les règles changent : Python utilise None, Swift nil, JavaScript notamment null et undefined. En SQL, NULL représente une information absente ou inconnue et se teste avec IS NULL.", "Une adresse e-mail absente n’est pas équivalente à une chaîne vide ou au nombre zéro.", ["null", "None", "nil", "undefined", "nullable", "nullables"]),
  term("exception", "Exception et gestion d’erreur", "Un signal indiquant qu’une opération ne peut pas continuer normalement. try encadre un traitement risqué, catch ou except traite une erreur attendue et finally réalise un nettoyage. Une erreur de syntaxe doit être corrigée avant que le programme puisse démarrer.", "Une conversion de texte invalide en nombre peut lever une exception ; on peut afficher un message compréhensible et demander une nouvelle saisie.", ["exception", "exceptions", "try", "catch", "except", "throw", "finally"]),
  term("console", "Console / terminal", "Un terminal est une interface pour saisir des commandes et lire leur sortie. Une console de développeur affiche les messages et erreurs d’un environnement comme le navigateur. Dans l’atelier, la console présente les entrées et sorties du programme ; elle n’est pas une fenêtre graphique native.", "print en Python ou console.log en JavaScript écrit dans la sortie, pas dans un titre HTML.", ["console", "terminal", "stdout", "stdin", "print", "println", "console.log", "printf", "echo"]),
  term("compilation", "Compilation", "Transformation d’un code source vers une autre représentation : code machine, bytecode ou autre langage. Une compilation réussie ne prouve pas que la logique du programme est correcte. Certains environnements compilent avant l’exécution, d’autres pendant.", "tsc transforme TypeScript en JavaScript ; GCC peut transformer C en programme natif.", ["compile", "compilation", "compilateur", "transpilation", "transpile", "tsc", "GCC"]),
  term("interpreteur", "Interpréteur", "Un programme qui exécute les instructions d’un langage ou une représentation intermédiaire. Un langage qualifié d’interprété peut aussi passer par une compilation interne. Le choix compilé/interprété décrit une façon d’exécuter, pas une opposition absolue entre tous les langages.", "CPython compile normalement Python en bytecode puis exécute ce bytecode.", ["interpreteur", "interprete", "interpretation", "CPython"]),
  term("bytecode", "Bytecode, JIT et AOT", "Le bytecode est une représentation intermédiaire entre le source et les instructions machine. JIT (Just-In-Time) signifie compilation pendant l’exécution ; AOT (Ahead-Of-Time), compilation avant l’exécution. Une machine virtuelle peut interpréter du bytecode ou en compiler une partie.", "Java produit des fichiers .class que la JVM sait exécuter.", ["bytecode", "JIT", "AOT"]),
  term("memoire", "Mémoire vive / RAM", "Random Access Memory : mémoire de travail utilisée pendant l’exécution. Les valeurs d’un tableau en mémoire peuvent disparaître à l’arrêt du programme ; les données enregistrées dans un fichier ou une base peuvent être rechargées.", "Un tableau de tâches conservé seulement dans un serveur Node.js repart de zéro après son redémarrage.", ["memoire", "RAM", "allocation", "pointeur", "pointeurs"]),
  term("reference", "Copie et référence", "Une copie crée une valeur distincte ; une référence permet d’accéder à un objet existant. Selon le langage et le type, copier une variable peut seulement copier une référence : les deux noms peuvent alors viser le même objet.", "En C++, const Profil& permet de consulter un profil existant sans le copier ni le modifier par cette référence.", ["reference", "references", "copie", "copier"]),
  term("bibliotheque", "Bibliothèque et dépendance", "Une bibliothèque est un ensemble de fonctions ou composants réutilisables. Une dépendance est un élément externe dont le projet a besoin. Un gestionnaire de paquets installe les versions de ces éléments.", "React est une bibliothèque ; un projet qui l’utilise déclare React comme dépendance.", ["bibliotheque", "bibliotheques", "dependance", "dependances", "package", "paquet", "paquets"]),
  term("framework", "Framework", "Un ensemble d’outils avec des conventions pour organiser une application. Il fournit une structure, des fonctions et des points où écrire ton propre code. Apprendre un framework demande aussi de comprendre le langage sur lequel il repose.", "Django utilise Python ; Laravel utilise PHP ; Spring Boot utilise Java.", ["framework", "frameworks"]),
  term("ide", "IDE et éditeur", "IDE signifie Integrated Development Environment : environnement de développement intégré. Il réunit l’édition, l’exécution et le débogage. Un éditeur de code est centré sur l’écriture et peut gagner d’autres fonctions avec des extensions.", "Android Studio est un IDE ; VS Code est un éditeur extensible ; notre atelier propose l’édition et certains modes d’exécution.", ["IDE", "editeur", "VS Code", "Visual Studio Code", "Android Studio", "Xcode"]),
  term("http", "HTTP / HTTPS", "Hypertext Transfer Protocol : protocole d’échange de requêtes et de réponses entre un client et un serveur. Une méthode annonce l’action, des en-têtes précisent le contexte et un corps peut transporter les données. HTTPS chiffre et authentifie le transport avec TLS.", "GET /articles/ demande une ressource ; une réponse 200 indique une réussite, 404 une ressource introuvable.", ["HTTP", "HTTPS", "GET", "POST", "PUT", "PATCH", "DELETE", "requete", "reponse"]),
  term("url", "URL et port", "Uniform Resource Locator : adresse d’une ressource. Elle peut préciser un protocole, un hôte, un port, un chemin et une chaîne de requête. Le port distingue un service sur une machine. localhost désigne ta propre machine.", "http://localhost:3000/taches?termine=false : 3000 est le port, /taches le chemin et termine=false un filtre transmis dans l’URL.", ["URL", "URLs", "localhost", "port", "endpoint", "endpoints"]),
  term("route", "Route", "Une règle qui associe un chemin, et souvent une méthode HTTP, à un traitement. Un paramètre dans le chemin identifie une ressource ; la query string transmet souvent des filtres. Une route côté navigateur peut simplement sélectionner un écran.", "/taches/7 désigne la tâche 7 ; /taches?termine=true demande une liste filtrée.", ["route", "routes", "routage", "router", "params", "query"]),
  term("api", "API et REST", "API signifie Application Programming Interface : interface de programmation. Elle décrit comment des programmes communiquent. REST signifie Representational State Transfer : un style d’architecture souvent utilisé pour exposer des ressources HTTP. Une API n’est pas nécessairement web, REST ou publique.", "Notre frontend peut demander une liste de publications à une API Django qui répond en JSON.", ["API", "APIs", "REST", "RESTful"]),
  term("json", "JSON", "JavaScript Object Notation : format texte d’échange de données. Il contient des objets, tableaux, textes, nombres, booléens et null, avec une syntaxe stricte. Il n’exécute pas des fonctions et n’est pas identique à un objet JavaScript en mémoire.", "{\"nom\":\"Tiana\",\"score\":3} est du JSON ; JSON.parse le convertit en valeur JavaScript.", ["JSON", "serialisation", "serialiseur", "serialiseurs", "deserialisation", "JSON.parse", "JSON.stringify"]),
  term("asynchrone", "Asynchronisme", "Une organisation où un résultat peut arriver plus tard sans bloquer tous les autres traitements. Une promesse représente le succès ou l’échec futur d’une opération. async et await facilitent sa lecture ; await ne transforme pas une longue opération synchrone en travail parallèle.", "Le navigateur peut continuer à réagir pendant qu’une requête réseau attend sa réponse.", ["asynchrone", "asynchronisme", "async", "await", "promesse", "promesses", "Promise", "Promises"]),
  term("callback", "Callback / fonction de rappel", "Une fonction transmise à une autre partie du programme pour qu’elle l’appelle au moment prévu. Il faut distinguer fournir la fonction et l’appeler immédiatement. Tous les callbacks ne sont pas asynchrones.", "bouton.addEventListener('click', saluer) transmet saluer ; saluer() l’appelle tout de suite.", ["callback", "callbacks", "rappel"]),
  term("evenement", "Événement et écouteur", "Un événement signale un fait : clic, saisie, chargement ou réception d’un message. Un écouteur est une fonction enregistrée pour réagir à cet événement. L’objet événement fournit des informations sur ce qui vient de se produire.", "Un écouteur de soumission peut empêcher le rechargement du formulaire et traiter les valeurs.", ["evenement", "evenements", "ecouteur", "ecouteurs", "listener", "listeners", "addEventListener", "onClick", "onChange", "onSubmit"]),
  term("module", "Module, import et export", "Un fichier qui expose des fonctions ou des valeurs et peut utiliser celles d’autres fichiers. export publie un élément ; import le récupère dans les systèmes de modules qui utilisent ces mots. Les règles de chemins et d’extensions dépendent de l’environnement.", "Un module de calcul peut être réutilisé dans plusieurs écrans sans recopier sa fonction.", ["module", "modules", "import", "export"]),
  term("npm", "npm et package.json", "npm est le gestionnaire de paquets de l’écosystème Node.js. package.json décrit un projet, ses dépendances et ses scripts. package-lock.json fixe les versions résolues pour reproduire l’installation. npm run lance un script nommé dans package.json.", "npm run dev lance le script dev ; npm ci installe les versions du fichier de verrouillage.", ["npm", "NPM", "package.json", "package-lock.json", "nodemon"]),
  term("node", "Node.js et V8", "Node.js exécute JavaScript hors du navigateur. V8 est son moteur JavaScript. Node.js fournit aussi des fonctions de fichiers, réseau et processus ; il n’inclut pas le document HTML du navigateur par défaut.", "node main.js exécute le fichier main.js dans Node.js.", ["Node.js", "Node", "V8"]),
  term("express", "Express et middleware", "Express simplifie un serveur Node.js. Un middleware est une fonction traversée pendant le traitement d’une requête ; il reçoit req, res et généralement next pour poursuivre la chaîne. L’ordre d’enregistrement des middlewares compte.", "express.json() lit un corps JSON ; une route peut ensuite consulter req.body.", ["Express", "middleware", "middlewares", "req", "res", "next"]),
  term("cli", "CLI", "Command-Line Interface : interface en ligne de commande. On écrit une commande dans un terminal et on lit sa sortie. Le dossier courant indique où cette commande cherche les fichiers du projet.", "php main.php exécute le fichier présent dans le dossier courant.", ["CLI", "ligne de commande"]),
  term("composant", "Composant", "Une partie réutilisable d’une interface, regroupant une présentation et éventuellement un comportement. On compose plusieurs petits composants pour obtenir un écran. Les paramètres rendent un composant personnalisable.", "Une CarteProfil peut être utilisée pour Tiana puis pour Amina en lui donnant des données différentes.", ["composant", "composants", "component", "components"]),
  term("jsx", "JSX et TSX", "JSX est une extension de syntaxe de JavaScript qui permet d’écrire une présentation ressemblant au HTML. Les expressions JavaScript se placent entre accolades. TSX est cette syntaxe dans un fichier TypeScript. Les outils transforment ces fichiers avant leur exécution.", "<h1>{prenom}</h1> affiche la valeur de prenom ; className s’utilise pour une classe CSS dans React DOM.", ["JSX", "TSX"]),
  term("props", "Props", "Abréviation de properties : données fournies par un composant parent à un composant enfant. Elles décrivent une entrée du composant. L’enfant doit demander au parent une modification plutôt que modifier directement les données reçues.", "<Carte nom=\"Tiana\" /> fournit la prop nom avec la valeur Tiana.", ["props", "prop", "defineProps"]),
  term("state", "State / état", "Les données qui décrivent la situation actuelle de l’interface : saisie, sélection, score, chargement. Une bibliothèque réactive sait mettre la présentation à jour quand cet état change selon ses règles. Une simple variable locale ne provoque pas toujours un nouveau rendu.", "En React, const [score, setScore] = useState(0) initialise score puis setScore demande une mise à jour.", ["state", "etat", "useState", "setState", "@State", "remember", "mutableStateOf"]),
  term("hook", "Hook et effet", "Un hook est une fonction spéciale qui relie un composant React à une capacité comme l’état ou un effet. Un effet synchronise le composant avec un système extérieur, par exemple un abonnement. Le nettoyage libère ce qui a été installé.", "useEffect peut installer un écouteur puis le retirer lors du nettoyage ; son tableau de dépendances indique quand cette synchronisation change.", ["hook", "hooks", "useEffect", "onMounted", "cycle de vie", "nettoyage"]),
  term("vite", "Vite", "Un outil qui lance un serveur de développement et prépare des fichiers optimisés pour la diffusion. Il transforme certaines syntaxes et recharge l’application pendant le développement. Il ne remplace pas le backend Django ou une base de données.", "npm run dev lance ici Vite ; npm run build prépare les fichiers de production.", ["Vite", "build", "Webpack"]),
  term("key", "key : identité dans une liste", "Une clé stable aide React ou Vue à reconnaître le même élément entre deux rendus. Elle doit distinguer les éléments frères et rester liée à la donnée, plutôt qu’à une position changeante.", "Pour des tâches triées, key={tache.id} conserve mieux leur identité que leur indice.", ["key", ":key"]),
  term("reactivite", "Réactivité", "Un mécanisme qui relie des valeurs observées aux traitements qui en dépendent. Quand une valeur change, les calculs ou l’affichage concernés peuvent être actualisés. Une valeur dérivée se calcule depuis d’autres valeurs au lieu d’être maintenue à la main.", "Dans Vue, une computed peut recalculer le total quand les quantités du panier changent.", ["reactivite", "reactif", "reactive", "reactives", "computed", "watch"]),
  term("directive", "Directive Vue", "Un attribut spécial compris par Vue dans le template. Il indique un comportement réactif : v-if conditionne un rendu, v-for répète des éléments, v-bind lie un attribut et v-on écoute un événement.", ":href est le raccourci de v-bind:href et @click celui de v-on:click.", ["directive", "directives", "v-if", "v-show", "v-for", "v-bind", "v-on"]),
  term("ref", "ref et .value", "Dans Vue, ref() crée une référence réactive. Dans le script, .value permet de lire ou modifier son contenu. Le template expose automatiquement la valeur d’une ref de premier niveau dans le contexte courant.", "const score = ref(0) puis score.value++ modifie le score ; {{ score }} l’affiche dans le template.", ["ref", "shallowRef"], ["vue-web"]),
  term("v-model", "v-model : liaison bidirectionnelle", "Une directive Vue qui associe la valeur d’un champ à une donnée réactive. Une modification du champ actualise la donnée ; une modification de la donnée actualise le champ. Elle utilise des conventions de propriétés et d’événements.", "<input v-model=\"nom\"> met nom à jour à chaque saisie selon le type de champ.", ["v-model", "bidirectionnelle", "two-way"]),
  term("sfc", "SFC et Composition API", "SFC signifie Single-File Component : composant Vue dans un fichier .vue. template décrit la présentation, script setup la logique et style l’apparence. La Composition API organise les comportements avec des fonctions réactives ; l’Options API les classe dans des options comme data et methods.", "Un petit App.vue peut réunir un compteur, son bouton et son style.", ["SFC", "Composition API", "Options API", "script setup", "Single File Component"]),
  term("store", "Store et état global", "Un espace partagé pour les données utilisées par plusieurs écrans. Il expose des valeurs et des actions pour les modifier. Il sert aux données qui ont réellement besoin d’être communes ; toutes les valeurs locales n’ont pas besoin d’y aller.", "Un panier peut être partagé entre la liste des produits et le récapitulatif de commande.", ["store", "stores", "Pinia", "Redux", "Context API", "useContext", "prop drilling"]),
  term("ssr", "SSR, SPA et SSG", "SSR signifie Server-Side Rendering : HTML produit sur le serveur pour une requête. SPA signifie Single-Page Application : application dont la navigation est largement gérée côté client. SSG signifie Static Site Generation : pages générées à la construction. Ces stratégies peuvent être combinées.", "Nuxt et Next.js proposent des stratégies de rendu au-dessus de Vue et de React.", ["SSR", "SPA", "SSG", "Nuxt", "Next.js"]),
  term("memoisation", "Mémorisation", "Réutiliser un résultat quand les entrées pertinentes n’ont pas changé. Cela peut éviter un calcul coûteux, mais comporte aussi un coût et ne remplace pas une conception correcte. Les dépendances déterminent quand le résultat doit être recalculé.", "useMemo peut mémoriser un calcul ; useCallback une référence de fonction. On optimise après avoir identifié un besoin.", ["memorisation", "useMemo", "useCallback", "React.memo"]),
  term("django", "Django", "Un framework web Python qui fournit des conventions pour recevoir des requêtes, traiter des données et produire des réponses. Son code s’exécute sur le serveur. Les templates HTML sont un mode de réponse possible ; une vue peut aussi produire du JSON.", "Une requête /articles/ peut être dirigée vers une vue qui lit la base puis affiche une liste.", ["Django"]),
  term("mtv", "MTV", "Model–Template–View : modèle, gabarit et vue. Le modèle décrit et manipule les données ; le template décrit leur présentation ; la vue reçoit une requête et prépare une réponse. Le routage choisit la vue avant ce traitement.", "Pour un blog : Article représente les données, liste.html leur présentation et une fonction de views.py prépare la liste.", ["MTV", "Model-Template-View"]),
  term("projet-django", "Projet Django", "La configuration globale d’un site : settings.py porte les réglages, urls.py les routes principales et les fichiers ASGI/WSGI permettent le démarrage serveur. manage.py exécute les commandes dans cette configuration. Plusieurs applications peuvent appartenir au même projet.", "django-admin startproject config . crée manage.py dans le dossier courant et le paquet config/.", ["startproject", "projet Django", "settings.py", "manage.py"], ["django-web"]),
  term("application-django", "Application Django", "Un module fonctionnel du projet, par exemple blog, comptes ou messagerie. startapp prépare notamment models.py, views.py, admin.py et un dossier migrations. Il faut ensuite déclarer l’application dans INSTALLED_APPS et relier ses URL selon les besoins.", "python manage.py startapp blog crée blog/ ; ajoute BlogConfig dans INSTALLED_APPS pour activer ses modèles et migrations.", ["startapp", "INSTALLED_APPS", "application Django"], ["django-web"]),
  term("template", "Template / gabarit", "Un modèle de présentation contenant du texte fixe et des emplacements pour des données. Un moteur de templates remplace ces emplacements pour produire le résultat. La syntaxe dépend de l’outil : DTL (Django Template Language) dans Django, Blade dans Laravel et template réactif dans Vue.", "Dans Django, {{ nom }} est remplacé par la valeur nom transmise par la vue dans son contexte.", ["template", "templates", "gabarit", "gabarits", "Blade", "DTL", "layout", "layouts"]),
  term("vue-django", "Vue Django / view", "Une fonction ou une classe qui reçoit une requête et prépare une réponse. Elle peut consulter les modèles, vérifier des droits et utiliser un template. Le mot « vue » de Django désigne cette logique serveur, pas simplement le dessin visible de la page.", "def accueil(request): return HttpResponse('Bonjour') est une vue minimale.", ["view", "views", "vue", "vues", "HttpResponse", "render"], ["django-web"]),
  term("venv", "venv et pip", "venv crée un environnement Python isolé pour les dépendances d’un projet. pip installe des paquets dans l’interpréteur choisi. Le dossier courant et l’environnement actif sont deux notions distinctes.", "Sous Windows, ./.venv/Scripts/python.exe -m pip install Django cible explicitement le Python de cet environnement.", ["venv", "pip", "environnement virtuel"]),
  term("orm", "ORM / mapping objet-relationnel", "Object-Relational Mapping : correspondance entre des objets du langage et des tables relationnelles. L’ORM traduit des opérations sur les modèles en SQL. Il aide à écrire les requêtes mais ne supprime pas le besoin de comprendre les tables, relations, permissions et coûts des requêtes.", "Task.objects.filter(done=False) demande à l’ORM Django de sélectionner les tâches non terminées.", ["ORM", "Object-Relational Mapping", "Eloquent", "JPA", "Hibernate", "mapping objet-relationnel"]),
  term("modele", "Modèle de données", "Une description des informations manipulées et de leurs règles. Dans un ORM, une classe modèle correspond généralement à une table, ses champs à des colonnes et une instance enregistrée à une ligne. Un nom de modèle n’est pas une autorisation d’accès.", "Task peut définir title, done et created_at pour représenter une tâche.", ["modele", "modeles", "Model", "Models", "entite", "entites"]),
  term("migration", "Migration de base de données", "Une étape versionnée qui fait évoluer la structure des tables : ajouter une colonne, créer une table ou modifier une contrainte. Générer une migration et l’appliquer sont deux actions distinctes. Les données déjà présentes nécessitent parfois une valeur de reprise.", "Django : makemigrations prépare les opérations ; migrate les applique à la base configurée.", ["migration", "migrations", "makemigrations", "migrate"]),
  term("crud", "CRUD", "Create, Read, Update, Delete : créer, lire, modifier et supprimer une donnée. Ce sont des opérations métier, pas les noms de quatre boutons obligatoires. Les droits et la validation doivent être appliqués à chaque opération concernée.", "Pour une tâche : ajouter son titre, lire la liste, cocher son état, puis supprimer la tâche choisie par son identifiant.", ["CRUD"]),
  term("admin", "Administration, utilisateurs et groupes", "Un espace de gestion interne des données et comptes. Dans Django, is_staff permet l’accès à l’admin, is_active doit autoriser le compte, puis les permissions déterminent les actions. Un groupe réunit des utilisateurs auxquels attribuer des permissions communes ; un superutilisateur actif possède des droits étendus.", "Un groupe Éditeurs peut recevoir view_article, add_article et change_article sans delete_article.", ["admin", "administration", "superutilisateur", "superuser", "is_staff", "is_superuser", "createsuperuser", "permissions", "autorisation", "autorisations"]),
  term("authentification", "Authentification et autorisation", "L’authentification vérifie qui est la personne ; l’autorisation décide ce qu’elle peut faire. Être connecté ne donne pas automatiquement le droit de modifier toutes les données. Un rôle est une façon de regrouper des capacités.", "Tiana peut être connectée et ne pouvoir modifier que ses propres publications.", ["authentification", "authentifier", "login", "authorization", "rôle administrateur", "rôles utilisateur"]),
  term("csrf", "CSRF", "Cross-Site Request Forgery : attaque qui tente de faire envoyer une action à l’insu d’une personne authentifiée. Un jeton CSRF relie notamment un formulaire à une session et permet au serveur de vérifier la requête. Ce jeton ne remplace pas les permissions ni la validation des données.", "Django insère {% csrf_token %} dans un formulaire POST ; Laravel propose @csrf.", ["CSRF", "csrf_token", "@csrf"]),
  term("mvc", "MVC", "Model–View–Controller : modèle, vue et contrôleur. Le modèle gère les données et règles, la vue les présente, le contrôleur reçoit une action et coordonne le traitement. Le découpage exact dépend du framework et diffère des noms utilisés par Django MTV.", "En Laravel, un contrôleur peut lire un modèle Eloquent puis renvoyer une vue Blade.", ["MVC", "controleur", "controller", "controllers"]),
  term("composer", "Composer", "Gestionnaire des dépendances PHP. composer.json décrit les paquets souhaités, composer.lock conserve les versions résolues et vendor/ contient les dépendances installées. Composer n’est pas le serveur qui répond au navigateur.", "composer install installe les paquets du projet exporté.", ["Composer", "composer.json", "composer.lock", "vendor"]),
  term("artisan", "Artisan", "Interface de commandes de Laravel. php artisan exécute une action dans un projet Laravel : lancer le serveur de développement, générer une classe ou appliquer des migrations. Les fichiers générés doivent ensuite être complétés.", "php artisan make:model Article crée une classe modèle Article.", ["Artisan"]),
  term("eloquent", "Eloquent", "L’ORM de Laravel. Un modèle PHP permet de lire et écrire des lignes d’une table, de déclarer des relations et d’appliquer des conversions. Les champs autorisés pour l’affectation de masse se configurent explicitement.", "Article::query()->where('publie', true)->get() lit les articles publiés.", ["Eloquent", "fillable", "guarded"], ["php-web"]),
  term("java", "Java", "Langage de programmation compilé en bytecode pour une machine virtuelle. Une classe regroupe des données et méthodes. Il est distinct de JavaScript, malgré une partie commune dans leurs noms.", "javac Main.java compile ; java Main exécute la classe principale dans un environnement Java standard.", ["Java"]),
  term("jdk", "JDK", "Java Development Kit : kit de développement Java. Il comprend notamment javac pour compiler, java pour exécuter et des outils de diagnostic. Le JRE est l’environnement d’exécution ; la JVM est la machine virtuelle qui exécute le bytecode.", "java -version vérifie l’exécution ; javac -version vérifie la présence du compilateur.", ["JDK", "JRE", "javac"]),
  term("jvm", "JVM", "Java Virtual Machine : machine virtuelle Java. Elle charge et exécute le bytecode, gère des aspects de la mémoire et peut compiler à la volée des passages du programme. Elle permet à plusieurs langages, dont Java et Kotlin, de partager un environnement.", "Un fichier .class est destiné à la JVM, pas directement au processeur comme un exécutable C natif.", ["JVM"]),
  term("maven", "Maven", "Outil Java de gestion de projet et de construction. Le fichier pom.xml décrit les dépendances et certaines étapes. Maven orchestre compilation, tests et empaquetage ; ce n’est pas le compilateur Java lui-même.", "mvn test lance les tests ; mvn spring-boot:run lance ici le projet Spring Boot.", ["Maven", "pom.xml", "mvn"]),
  term("annotation", "Annotation", "Une information attachée à du code pour un outil ou un framework. En Java, elle commence souvent par @. Sa signification dépend de ce qui la lit : une annotation n’agit pas comme une instruction ordinaire isolée.", "@RestController indique à Spring de traiter une classe comme un contrôleur dont les résultats forment les réponses.", ["annotation", "annotations", "@RestController", "@Entity", "@Valid", "@Composable", "@FXML"]),
  term("injection", "Injection de dépendances", "Fournir à un objet les autres objets dont il a besoin, au lieu de lui faire construire lui-même chaque dépendance. Dans Spring, le conteneur peut choisir et fournir un composant par le constructeur. Cela facilite aussi le remplacement d’un service dans un test.", "Un contrôleur reçoit un service de tâches dans son constructeur.", ["injection", "dependance injectee", "bean", "beans"]),
  term("dto", "DTO et validation", "Data Transfer Object : objet de transfert de données. Il décrit la forme des données qui entrent ou sortent d’une interface. Une validation vérifie les contraintes métier et de format ; elle est distincte du simple décodage JSON.", "Un DTO de création peut contenir title sans accepter un identifiant ou un rôle administrateur fourni par le client.", ["DTO", "validation", "valider", "validator", "validators"]),
  term("sql", "SQL", "Structured Query Language : langage de requêtes structuré pour des données relationnelles. Il décrit les résultats ou changements souhaités ; le moteur choisit un plan d’exécution. SQL est le langage, SQLite et PostgreSQL sont des logiciels qui l’implémentent.", "SELECT nom FROM contacts; lit la colonne nom dans la table contacts.", ["SQL", "SELECT", "INSERT", "UPDATE", "DELETE", "CREATE TABLE"]),
  term("sgbd", "SGBD / DBMS", "Système de gestion de base de données ; en anglais Database Management System. Il stocke, recherche et modifie les données et applique des contraintes. Chaque système possède des particularités de types, syntaxe, concurrence et administration.", "SQLite est embarqué ; PostgreSQL, MySQL et SQL Server fonctionnent souvent comme des serveurs séparés.", ["SGBD", "DBMS", "PostgreSQL", "MySQL", "SQL Server"]),
  term("sqlite", "SQLite dans cet atelier", "Un moteur SQL embarqué : l’application utilise une bibliothèque, sans serveur de base distinct. Ici sql.js fait fonctionner SQLite dans le navigateur. Le SQL des exemples est donc du SQL SQLite, avec ses types et ses particularités.", "PRAGMA table_info(contacts); inspecte une table SQLite ; cette commande ne se transpose pas telle quelle dans PostgreSQL.", ["SQLite", "sql.js", "PRAGMA"]),
  term("table", "Table, colonne et ligne", "Une table organise des données de même structure. Une colonne décrit un champ et son type ; une ligne représente un enregistrement. Un résultat SELECT est aussi présenté en colonnes et lignes mais n’est pas nécessairement une nouvelle table enregistrée.", "Dans contacts(id, nom, email), un contact est une ligne et email une colonne.", ["table", "tables", "colonne SQL", "ligne SQL", "enregistrement", "enregistrements"]),
  term("cle-primaire", "Clé primaire", "Un champ ou ensemble de champs qui identifie une ligne de manière unique. On l’utilise pour retrouver précisément une donnée et pour les relations. Dans SQLite, INTEGER PRIMARY KEY a un comportement particulier lié au rowid.", "Deux contacts peuvent avoir le même nom mais doivent avoir des identifiants différents.", ["cle primaire", "PRIMARY KEY", "identifiant", "rowid"]),
  term("cle-etrangere", "Clé étrangère", "Une colonne ou un ensemble de colonnes qui fait référence à une clé d’une autre table ou de la même table. La contrainte garantit la cohérence des relations quand elle est activée. Dans SQLite, son application se règle par connexion avec PRAGMA foreign_keys.", "commandes.client_id référence clients.id : chaque commande est rattachée à un client existant.", ["cle etrangere", "cles etrangeres", "FOREIGN KEY", "ForeignKey", "REFERENCES", "ManyToManyField"]),
  term("jointure", "Jointure / JOIN", "Une opération qui combine des lignes de plusieurs sources selon une condition. INNER JOIN conserve les correspondances ; LEFT JOIN conserve aussi les lignes de gauche sans correspondance, avec NULL pour les colonnes manquantes de droite.", "clients JOIN commandes ON commandes.client_id = clients.id associe les commandes à leurs clients.", ["jointure", "jointures", "JOIN", "INNER JOIN", "LEFT JOIN", "RIGHT JOIN"]),
  term("contrainte", "Contrainte SQL", "Une règle appliquée par le moteur aux données : NOT NULL impose une valeur, UNIQUE interdit les doublons concernés, CHECK vérifie une condition et une clé étrangère vérifie une relation. La validation dans un formulaire et les contraintes en base se complètent.", "CHECK (montant_centimes >= 0) refuse un montant négatif.", ["contrainte", "contraintes", "UNIQUE", "CHECK", "NOT NULL"]),
  term("transaction", "Transaction", "Un groupe d’opérations qui réussissent ensemble ou sont annulées ensemble selon le contexte. COMMIT valide et ROLLBACK annule les modifications de la transaction. Les verrous, niveaux d’isolation et effets des commandes de structure varient selon le SGBD.", "Pour transférer un montant, débiter un compte et créditer l’autre doivent former une opération cohérente.", ["transaction", "transactions", "COMMIT", "ROLLBACK", "atomic"]),
  term("index", "Index de base de données", "Une structure supplémentaire qui peut accélérer certaines recherches et certains tris. Elle occupe de l’espace et augmente le travail lors des écritures. Le moteur choisit son utilisation selon la requête et ses estimations.", "Un index sur nom peut aider une recherche compatible ; EXPLAIN QUERY PLAN montre le plan choisi par SQLite.", ["index", "indexation", "EXPLAIN", "QUERY PLAN"], ["lang-sql", "django-web", "php-web", "java-web"]),
  term("agregation", "Agrégation SQL", "Un calcul qui rassemble plusieurs lignes en une valeur : COUNT compte, SUM additionne, AVG calcule une moyenne. GROUP BY crée des groupes ; HAVING filtre les groupes après agrégation tandis que WHERE filtre les lignes avant.", "SELECT client_id, SUM(montant_centimes) FROM commandes GROUP BY client_id; calcule un total par client.", ["agregation", "GROUP BY", "HAVING", "COUNT", "AVG", "SUM"]),
  term("odm", "ODM et Mongoose", "Object Document Mapping : correspondance entre objets et documents d’une base documentaire. Mongoose est un ODM pour MongoDB ; ce n’est pas un ORM relationnel. Un schéma décrit la forme et les validations, mais les données restent des documents.", "Un modèle Produit Mongoose peut valider un nom et enregistrer un document MongoDB.", ["ODM", "Mongoose", "MongoDB", "NoSQL", "schema", "schemas"], ["node-web"]),
  term("jwt", "JWT", "JSON Web Token : format de jeton contenant des informations appelées claims. Une signature permet de vérifier l’intégrité et l’émetteur selon la configuration ; elle ne chiffre pas le contenu. Le serveur doit aussi vérifier expiration, destinataire et autorisations nécessaires.", "Un jeton peut identifier un utilisateur ; chaque route privée doit encore appliquer ses règles d’accès.", ["JWT", "jsonwebtoken", "token", "tokens", "jeton", "jetons"]),
  term("hachage", "Hachage et chiffrement", "Le hachage produit une empreinte à sens unique ; le chiffrement permet de retrouver les données avec une clé. Pour les mots de passe, on utilise une fonction de dérivation adaptée avec un sel et un coût de calcul. Un sel différencie des mots de passe identiques ; il n’est pas une clé secrète.", "bcrypt sert à vérifier un mot de passe sans conserver son texte en clair ; Fernet chiffre et déchiffre des données avec une clé.", ["hachage", "hacher", "chiffrement", "bcrypt", "Scrypt", "Fernet", "sel"]),
  term("cors", "CORS", "Cross-Origin Resource Sharing : mécanisme par lequel un serveur indique au navigateur quelles origines peuvent lire certaines réponses. Il ne constitue pas une authentification, et n’empêche pas un autre programme d’envoyer une requête.", "Un frontend sur localhost:5173 peut avoir besoin d’une autorisation CORS pour lire un backend sur un autre port.", ["CORS", "cors"]),
  term("socket", "WebSocket et Socket.IO", "WebSocket est un protocole pour échanger des messages dans les deux sens sur une connexion persistante. Socket.IO est une bibliothèque avec son propre protocole, des événements et des mécanismes de reconnexion ; ce n’est pas exactement une socket WebSocket brute.", "Un serveur de discussion peut pousser un nouveau message vers les participants connectés.", ["WebSocket", "WebSockets", "Socket.IO", "socket.io", "socket"]),
  term("session", "Session et cookie", "Une session conserve un état associé à un utilisateur entre plusieurs requêtes. Un cookie est une petite donnée échangée avec le navigateur ; il peut porter l’identifiant de session. L’emplacement des données de session dépend de la configuration.", "Après connexion, le navigateur renvoie un cookie et le serveur retrouve la session correspondante.", ["session", "sessions", "cookie", "cookies"]),
  term("sdk", "SDK", "Software Development Kit : kit de développement logiciel. Il rassemble des outils, bibliothèques et interfaces nécessaires pour construire une application pour une cible. Sa version détermine notamment les capacités disponibles.", "Le SDK Android fournit les outils et API Android ; le SDK Flutter fournit notamment les commandes flutter.", ["SDK"]),
  term("emulateur", "Émulateur et simulateur", "Un environnement qui reproduit certains comportements d’un appareil pour tester une application sur l’ordinateur. Il aide à explorer des tailles et versions, mais ne remplace pas tous les essais sur un appareil réel.", "Android Studio peut lancer un téléphone virtuel ; Xcode propose un simulateur iOS.", ["emulateur", "simulateur", "AVD"]),
  term("activity", "Activity Android", "Un composant Android qui représente un point d’entrée d’interaction. Il reçoit des événements de cycle de vie : création, démarrage, pause, arrêt. Une application peut avoir une ou plusieurs activités, chacune pouvant héberger plusieurs écrans.", "onCreate prépare l’activité ; un Intent peut demander l’ouverture d’une autre activité.", ["Activity", "activite", "activites", "onCreate", "Intent"]),
  term("gradle", "Gradle", "Un outil qui orchestre les étapes de construction et les dépendances. Dans Android, le plugin Android lui ajoute les tâches nécessaires pour compiler les sources, traiter les ressources et produire un paquet installable.", "Le wrapper gradlew ou gradlew.bat lance la version de Gradle prévue par le projet.", ["Gradle", "gradlew", "build.gradle", "build.gradle.kts"]),
  term("apk", "APK, DEX et ART", "APK signifie Android Package : archive installable d’une application Android. DEX signifie Dalvik Executable : format de bytecode Android. ART signifie Android Runtime : environnement qui exécute ce code avec ses stratégies d’interprétation et de compilation.", "L’outil de construction produit un APK ; le téléphone l’installe puis Android lance ses composants.", ["APK", "DEX", "ART"]),
  term("xml", "XML", "eXtensible Markup Language : langage de balisage extensible. Il décrit des données avec des éléments et attributs. Les noms de balises autorisés et leur rôle sont définis par l’outil qui utilise le fichier, par exemple Android ou JavaFX.", "Dans Android, un TextView décrit une vue texte ; en FXML, un Label décrit un contrôle JavaFX.", ["XML", "FXML", "TextView"]),
  term("composable", "Composable et recomposition", "Une fonction marquée @Composable décrit une partie d’interface Compose. Une recomposition réexécute les parties concernées quand des données observées changent. Évite d’y lancer sans contrôle des effets extérieurs comme une requête réseau.", "Text(text = nom) décrit un texte ; un état observé peut déclencher son actualisation.", ["composable", "composables", "recomposition", "@Composable"]),
  term("modifier", "Modifier et disposition Compose", "Modifier est une chaîne de réglages appliqués à un composable : taille, espaces, fond, interaction. L’ordre des réglages peut modifier le résultat. Row, Column et Box organisent les enfants sur une ligne, une colonne ou une superposition.", "Modifier.padding(16.dp).background(...) et l’ordre inverse ne dessinent pas forcément le même fond.", ["Modifier", "modifiers", "Column", "Row", "Box", "dp", "sp"], ["compose-mobile"]),
  term("viewmodel", "ViewModel et état d’écran", "Un objet qui prépare et conserve des données pour l’interface selon l’architecture choisie. Il sépare les actions métier de la présentation. Un état d’écran doit représenter aussi le chargement, les erreurs et l’absence de données si nécessaire.", "Un ViewModel de panier peut exposer les articles et un total calculé.", ["ViewModel", "StateFlow", "LiveData", "ObservableObject", "@Published", "@StateObject"]),
  term("coroutine", "Coroutine et Flow", "Une coroutine est un calcul qui peut suspendre son exécution sans bloquer le thread qui l’héberge. suspend signale une fonction pouvant suspendre. Flow représente un flux de valeurs ; un dispatcher choisit l’environnement d’exécution.", "Dispatchers.IO convient à certains travaux bloquants d’entrées-sorties ; Main sert aux opérations d’interface Android.", ["coroutine", "coroutines", "Flow", "suspend", "dispatcher", "dispatchers"]),
  term("python", "Python", "Langage généraliste dont l’indentation fait partie de la syntaxe. Son implémentation courante CPython compile le texte en bytecode puis l’exécute. Un script peut lire des données, calculer et produire une sortie sans interface graphique.", "print('Bonjour') affiche un texte ; les apostrophes délimitent la chaîne et ne sont pas affichées.", ["Python", "print"]),
  term("indentation", "Indentation", "Le décalage horizontal au début d’une ligne pour montrer des blocs. En Python, il délimite réellement les suites d’instructions et doit rester cohérent. Dans HTML, CSS et beaucoup d’autres langages, il améliore surtout la lecture.", "Après if score > 0: en Python, les instructions du bloc sont décalées, habituellement avec quatre espaces.", ["indentation", "indenter", "indente"]),
  term("main", "main et point d’entrée", "L’endroit par lequel commence l’exécution d’un programme selon son environnement. Certains langages demandent une fonction main ; un script peut être exécuté depuis le haut du fichier. Le nom du fichier et le point d’entrée sont liés par des conventions propres au projet.", "int main(void) démarre un programme C ; un script Python n’a pas besoin d’une fonction main obligatoire.", ["main", "point d’entree", "point d'entree"]),
  term("customtkinter", "CustomTkinter et boucle d’événements", "Une bibliothèque Python d’interface basée sur Tkinter. CTk crée une fenêtre, les widgets décrivent ses contrôles et mainloop attend puis distribue les événements. La fenêtre native se lance sur un système disposant d’un environnement graphique.", "command=compteur.incrementer transmet une méthode à un bouton ; elle sera appelée au clic.", ["CustomTkinter", "CTk", "CTkButton", "mainloop", "Tkinter"]),
  term("gui", "GUI / interface graphique", "Graphical User Interface : interface graphique. La personne interagit avec des fenêtres, boutons, champs et menus. Un widget est un élément de cette interface. Une application console échange plutôt du texte via un terminal.", "Une fenêtre avec un champ de saisie et un bouton Valider est une GUI.", ["GUI", "interface graphique", "interfaces graphiques", "widget", "widgets"]),
  term("electron", "Electron et IPC", "Electron assemble Node.js, Chromium et des API de bureau. Le processus principal gère les fenêtres ; le renderer présente l’interface. IPC signifie Inter-Process Communication : communication entre processus. Une passerelle preload expose des capacités précises à l’interface.", "Le renderer peut demander une information au processus principal via une API limitée définie dans preload.", ["Electron", "IPC", "BrowserWindow", "renderer", "preload", "contextBridge"]),
  term("typescript", "TypeScript", "Langage qui ajoute des informations de types à JavaScript. Son compilateur peut détecter des incohérences puis produire du JavaScript. Les types sont principalement effacés à la compilation : ils ne valident pas automatiquement une requête reçue à l’exécution.", "const age: number = 23 indique que age attend un nombre.", ["TypeScript"]),
  term("interface", "Interface utilisateur et interface de type", "En TypeScript, une interface décrit la forme attendue d’une valeur, par exemple les propriétés d’un profil. Elle ne crée ni objet ni contrôle automatique à l’exécution. Le mot interface peut aussi désigner une présentation utilisateur dans un autre contexte.", "interface Profil { nom: string } décrit un objet possédant un texte nom.", ["interface", "interfaces", "contrat"], ["lang-typescript", "react-web", "vue-web", "react-native-mobile"]),
  term("inference", "Inférence de types", "La déduction d’un type par l’outil à partir des valeurs et du contexte. On n’a donc pas toujours besoin d’écrire une annotation. Cette déduction respecte les règles du langage ; elle ne devine pas les données externes à l’exécution.", "let score = 0 permet à TypeScript de déduire number.", ["inference", "inference de types"]),
  term("unknown", "unknown et réduction de type", "En TypeScript, unknown représente une valeur dont le type n’est pas encore connu. Des vérifications permettent de réduire les possibilités avant d’utiliser la valeur. C’est différent de any, qui désactive une partie des vérifications.", "typeof valeur === 'string' permet ensuite d’utiliser certaines opérations de texte dans cette branche.", ["unknown", "any", "narrowing", "garde de type"]),
  term("union", "Union et propriété facultative", "Une union TypeScript autorise plusieurs types, séparés par |. Le symbole ? après une propriété la rend facultative. Il faut vérifier les possibilités avant une opération qui ne convient qu’à l’une d’elles.", "telephone?: string peut être absent ; score: number | null peut être numérique ou nul.", ["union", "unions", "optionnel", "optionnels", "facultative", "facultatif"], ["lang-typescript", "react-web", "react-native-mobile"]),
  term("generique", "Générique", "Une façon de paramétrer une fonction ou une structure avec un type, pour la réutiliser en conservant des relations de types. T est un nom conventionnel, pas un type particulier prédéfini. Une contrainte limite les types acceptés.", "Une fonction identite<T>(valeur: T): T conserve la relation entre le type reçu et celui renvoyé.", ["generique", "generiques", "generic", "generics"]),
  term("nodegui", "NodeGui, Qt et Qode", "NodeGui expose des widgets Qt à JavaScript et TypeScript pour les applications de bureau. Qt est une bibliothèque d’interface native ; Qode est l’environnement Node adapté utilisé par cet écosystème. La fenêtre native se lance sur le système local.", "QLabel affiche du texte ; QPushButton produit notamment l’événement clicked.", ["NodeGui", "Qt", "Qode", "QLabel", "QPushButton", "FlexLayout"]),
  term("php", "PHP", "PHP: Hypertext Preprocessor : le nom PHP apparaît dans son propre développement, ce que l’on appelle un acronyme récursif. Langage généralement interprété par un moteur qui prépare des instructions intermédiaires. Il peut s’exécuter dans un terminal ou sur un serveur ; le navigateur reçoit sa sortie et non le code PHP.", "<?php echo 'Bonjour'; écrit Bonjour. Le point-virgule termine l’instruction.", ["PHP", "readline"]),
  term("swift", "Swift et SwiftUI", "Swift est un langage généralement compilé en code machine. SwiftUI est une bibliothèque déclarative d’interface pour les plateformes Apple. Une structure qui adopte View fournit une propriété body décrivant sa présentation.", "Text(\"Bonjour\") décrit une vue texte SwiftUI.", ["Swift", "SwiftUI"]),
  term("protocole", "Protocole Swift", "Un contrat qui décrit des propriétés et méthodes qu’un type doit fournir. Le type qui adopte ce protocole s’engage à fournir ces capacités. Cela ne constitue pas nécessairement un héritage de classe.", "Une structure conforme à View doit fournir un body compatible avec SwiftUI.", ["protocole", "protocol", "protocoles"], ["swift-mobile"]),
  term("optionnel", "Optionnel Swift", "Un type qui représente soit une valeur, soit son absence, nil. Il faut traiter l’absence avant de manipuler la valeur comme un texte ou un nombre ordinaire. Forcer un déballage avec ! peut échouer si la valeur est absente.", "if let nom = nomFacultatif ouvre un bloc seulement si une valeur existe.", ["optionnel", "optionnels", "nil", "if let", "guard let"], ["swift-mobile"]),
  term("flutter", "Flutter", "Boîte à outils d’interface multiplateforme utilisant Dart. Les widgets décrivent l’interface et son organisation. Le moteur Flutter produit le rendu selon la cible ; ce n’est pas un langage distinct de Dart.", "MaterialApp prépare une application et Scaffold organise un écran Material.", ["Flutter", "MaterialApp", "Scaffold", "StatelessWidget", "StatefulWidget"]),
  term("dart", "Dart", "Langage utilisé par Flutter. Il offre un système de types, des classes et des opérations asynchrones. Selon la cible et le mode, il utilise JIT, AOT ou une compilation vers des technologies web.", "String nom = 'Tiana'; crée une variable texte typée.", ["Dart", "null safety"]),
  term("expo", "Expo", "Un ensemble d’outils et de bibliothèques autour de React Native. Expo Go est une application permettant d’ouvrir des projets compatibles. Certaines fonctionnalités natives nécessitent une construction de développement spécifique.", "Le serveur de développement peut proposer un code QR pour ouvrir le projet sur un téléphone compatible.", ["Expo", "Expo Go"]),
  term("native", "Natif / multiplateforme", "Natif désigne un programme ou une interface intégrés à la plateforme visée. Multiplateforme signifie qu’une partie du code peut être partagée entre plusieurs systèmes. Le partage ne supprime pas toutes les différences de construction, permissions et interactions.", "Un projet partagé peut nécessiter un réglage Android et un autre iOS pour la même fonctionnalité.", ["natif", "native", "natifs", "natives", "multiplateforme"]),
  term("stockage", "Stockage local et persistance", "La persistance conserve des données au-delà d’une exécution ou d’un rafraîchissement. localStorage stocke de petites chaînes côté navigateur ; IndexedDB gère des données structurées. Un enregistrement local reste lié au navigateur et à l’appareil concernés.", "Une liste de tâches stockée peut être relue après le rechargement ; une variable en mémoire seule ne suffit pas.", ["localStorage", "IndexedDB", "persistance", "persistante", "stockage", "SharedPreferences", "SwiftData"]),
  term("deploiement", "Déploiement et environnement", "Le déploiement installe et configure une application pour qu’elle soit accessible dans son environnement cible. Développement, test et production peuvent avoir des réglages différents. Une variable d’environnement transmet une configuration au programme sans modifier directement sa logique.", "Le port, l’adresse de la base et les secrets de serveur sont des configurations d’environnement.", ["deploiement", "production", "variable d’environnement", ".env", "dotenv", "DEBUG", "SECRET_KEY"]),
  term("docker", "Docker et conteneur", "Docker prépare une image décrivant un environnement logiciel et lance des conteneurs à partir de cette image. Un conteneur est une instance d’environnement d’exécution. Dans DevAfrica, l’image du compilateur fournit les outils des exercices console.", "npm run compiler:build construit l’image ; le bouton Exécuter demande ensuite une exécution.", ["Docker", "conteneur", "conteneurs", "Dockerfile"]),
  term("drf", "DRF", "Django REST Framework : bibliothèque utilisée avec Django pour construire des API. Un serializer transforme ou valide des données ; une vue ou un ViewSet organise les opérations ; les permissions décident qui peut les utiliser.", "Un frontend React peut consommer le JSON d’une liste de publications produite par DRF.", ["DRF", "Django REST Framework", "ViewSet", "ViewSets"]),
];

function normalized(text: string) { return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase(); }
function escaped(text: string) { return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
const matchers = new Map(learningGlossary.map((entry) => [entry.id, entry.aliases.map((alias) => new RegExp("(^|[^a-z0-9_])" + escaped(normalized(alias)) + "(?=$|[^a-z0-9_])", "i"))]));
export function findLearningTerms(text: string, courseId?: string, required: string[] = []) {
  const content = normalized(text);
  const excluded = courseId === "lang-sql" ? ["http", "route", "tableau", "reference", "state", "main"] : courseId === "html-css-web" ? ["classe", "instance", "constructeur", "methode", "tableau", "main", "table", "state", "objet"] : [];
  return learningGlossary.filter((entry) => !excluded.includes(entry.id) && (!entry.courses || !courseId || entry.courses.includes(courseId)) && (required.includes(entry.id) || matchers.get(entry.id)!.some((matcher) => matcher.test(content))));
}
